"""Рядки 4600–4603 (ОЦІНКА-6Б-34): записані відповіді сцени «Оціни образ» ЖИВІ-19 А/10, А/15 і ЖИВІ-22 А/05, А/06 (А/15, А/06 —
`OTSINKA_F2=L`) тим кодом, що в теці аргументу (типово `.`): речі (`речі_з_відповіді`; невидима — повтор, як показ), кадри рамок
фігурами стенда (`ОЦІНКА_ФІГУРИ` рв6_стенд.js, ріжуться як `пікселіРечіП`; без рамки — ціле фото), `суд`, і записана «ОЦІНКА:
відповідь» — `прийняти_оцінку`; «інший промпт» — повтор формату показу. Друкує образ, слот, вид, слово й вимір кожної речі, «Що вдало» після сторожа й опори суду.
Кращим: образ не порожній; бордове ф1 — бордове або без виміру; взуття ф2 — взуттям; «Що вдало» або повтор з опорами.
Запуск: cd джерела && python3 проби/оцінка_6б_4600.py [тека джерел іншої збірки]"""
import base64, json, subprocess, sys
sys.path.insert(0, sys.argv[1] if len(sys.argv) > 1 else "."); import оцінка_образу as О
git = lambda *а: subprocess.run(["git", "-c", "core.quotepath=false", *а], capture_output=True, text=True).stdout
П = lambda т, з=0: [(x + з, y) for x, y in т]
ЧОБІТ = lambda з, к, п: [(к, П([(98, 170), (190, 170), (194, 336), (214, 370), (248, 393), (266, 418), (270, 446), (264, 462), (98, 462)], з)), (п, П([(140, 462), (268, 462), (266, 470), (256, 474), (140, 474)], з)), (п, П([(98, 462), (136, 462), (134, 480), (100, 480)], з)), (п, П([(98, 170), (190, 170), (190, 180), (98, 180)], з))]
Г = lambda з: П([(100, 170), (200, 170), (200, 380), (270, 400), (270, 480), (70, 480), (70, 380), (100, 380)], з)
Ф1 = (600, 800, (239, 233, 225), [((125, 127, 99), [(170, 90), (430, 90), (480, 130), (480, 440), (430, 440), (430, 470), (170, 470), (170, 440), (120, 440), (120, 130)]), ((207, 216, 227), [(250, 110), (350, 110), (350, 400), (250, 400)]), ((107, 31, 42), [(200, 520), (400, 520), (430, 760), (170, 760)])])
Ф2 = {False: (600, 600, (140, 150, 160), ЧОБІТ(0, (230, 223, 210), (107, 91, 76)) + ЧОБІТ(260, (29, 28, 28), (74, 70, 70))), True: (600, 600, (140, 150, 160), [((230, 223, 210), Г(0)), ((29, 28, 28), Г(260))])}
def всередині(x, y, п): return sum((ay > y) != (by > y) and x < (bx - ax) * (y - ay) / (by - ay) + ax for (ax, ay), (bx, by) in zip(п, п[1:] + п[:1])) % 2
def кадр(фото, р):
    W, H, тло, фіг = фото; л, в, п, н = [(р or {}).get(к, д) for к, д in (("ліво", 0), ("верх", 0), ("право", 1000), ("низ", 1000))]
    dx, dy = ((п - л) * .12, (н - в) * .12) if р else (0, 0); л2, в2, п2, н2 = max(0, л - dx), max(0, в - dy), min(1000, п + dx), min(1000, н + dy)
    x0, x1, y0, y1 = [round(a / 1000 * s) for a, s in ((л2, W), (п2, W), (в2, H), (н2, H))]; к = min(1, 128 / max(x1 - x0, y1 - y0, 1))
    w, h = max(1, round((x1 - x0) * к)), max(1, round((y1 - y0) * к)); тч = lambda x, y: next((к_ for к_, ф in reversed(фіг) if всередині(x + .5, y + .5, ф)), тло)
    вих = dict(дані=base64.urlsafe_b64encode(bytes(b for j in range(h) for i in range(w) for b in тч(x0 + i / к, y0 + j / к))).decode(), ширина=w, висота=h)
    return dict(вих, ядро={к_: round((v - о) / (м - о) * 1000) for к_, v, о, м in (("ліво", л, л2, п2), ("верх", в, в2, н2), ("право", п, л2, п2), ("низ", н, в2, н2))}) if р else вих
ФІД = [{"ід": "ф1"}, {"ід": "ф2"}]; git("fetch", "-q", "origin", "claude/zhyvi-22")   # профіль стенда — вхід прогону Ж22 №5, без каталогу (зміни крамниці тут не судяться)
вх = {к: v for к, v in json.loads(git("show", "origin/claude/zhyvi-22:аудит/живі_22/А/05_ж1_оціни_образ_6б/вердикти.txt"))["прогони"][0]["спільне"]["вхід_прогону"].items() if к not in ("каталог", "кеш_кольорів")}
for ж, сцени in (("19", ("10", "15")), ("22", ("05", "06"))):
    Гл = "origin/claude/zhyvi-" + ж; git("fetch", "-q", "origin", "claude/zhyvi-" + ж); шл = git("ls-tree", "-r", "--full-tree", "--name-only", Гл, "аудит/живі_%s/А" % ж).split("\n")
    for сц in сцени:
        тека = "/".join(next(ф for ф in шл if ф.split("/")[3].startswith(сц + "_")).split("/")[:4])
        фото = {"ф1": Ф1, "ф2": Ф2[сц in ("15", "06")]}; речі = с = None
        for ф in sorted(х for х in шл if х.startswith(тека + "/VIDPOVIDI/") and ("ОЦІНКА_р" in х or "ОЦІНКА_ві" in х or "інший" in х)):
            т = git("show", "%s:%s" % (Гл, ф)).split("── ВІДПОВІДЬ", 1)[1].split("\n", 1)[1]; н = ф.split("/")[-1][6:8]
            if "ОЦІНКА_ві" not in ф:
                речі = О.речі_з_відповіді(т, ФІД); пікс = {х["ід"]: кадр(фото[х["фото"]], х.get("рамка")) for х in речі["речі"]}
                інші = {х["ід"]: {ф_: кадр(фото[ф_], х["рамка"]) for ф_ in фото if ф_ != х["фото"]} for х in речі["речі"] if х.get("рамка") and х.get("колір")}
                с = О.суд(dict(вх, речі=речі["речі"], пікселі=пікс, пікселі_фото=інші, сценарій_оцінки={}, крамниця=False))
                print("\nЖ%s %s/%s речі: образ %s · запасні %s%s" % (ж, сц, н, с["образ"], с["запасні"], " · " + (с.get("чому") or речі["причина"] or "") if с.get("чому") or речі["причина"] else ""))
                for х in с["речі"]: print("   %-5s %-16s слот %-11s вид %-11s слово %-9s → %s" % (х["ід"], (х.get("назва") or "")[:16], х.get("слот"), х.get("вид") or "—", х.get("колір"), ((х.get("вимір") or {}).get("hex") or "—") + " " + ((х.get("вимір") or {}).get("слово") or "")))
            elif с and с["образ"]:
                о = О.прийняти_оцінку(т, с); оп = getattr(О, "опори_вдалого", lambda с_: None)(с); пв = getattr(О, "повтор_вдалого", lambda с_, к: None)(с, о["картка"])
                print("   %s відповідь: «Що вдало» %d %s · знято %s · опори %s · повтор %s" % (н, len(о["картка"]["вдало"]), [п["про"] for п in о["картка"]["вдало"]], [х["чому"] for х in о["сторож"] if х["де"].startswith("works")], оп if оп is not None else "—", "так" if пв else "—"))
